import{_ as i,C as r,o as n,c as s,a6 as a,E as t}from"./chunks/framework.CKIbuWFA.js";const g=JSON.parse('{"title":"Diagnosticar una operación fallida","description":"","frontmatter":{"title":"Diagnosticar una operación fallida","docId":"user.preferences.troubleshooting","translationKey":"user.preferences.troubleshooting","locale":"es","audience":"user","featureStatus":"available","contentStatus":"reviewed","sourceLocale":"en","sourceRevision":"40d8c5706363baa28e4114397696c8c2adb320843271a00efb3772be0322d5e2","translationRevision":"701dc90d1687589711190ee5d4fc75e69b186a59827e1aa27236c33314a7ba9f","order":30},"headers":[],"relativePath":"es/user/preferences/troubleshooting.md","filePath":"es/user/preferences/troubleshooting.md","lastUpdated":1794611623000}'),l={name:"es/user/preferences/troubleshooting.md"};function c(d,e,u,p,m,f){const o=r("DemoFrame");return n(),s("div",null,[e[0]||(e[0]=a('<h1 id="diagnose-a-failed-operation" tabindex="-1">Diagnosticar una operación fallida <a class="header-anchor" href="#diagnose-a-failed-operation" aria-label="Permalink to &quot;Diagnosticar una operación fallida {#diagnose-a-failed-operation}&quot;">​</a></h1><h2 id="goal-and-prerequisites" tabindex="-1">Objetivo y requisitos <a class="header-anchor" href="#goal-and-prerequisites" aria-label="Permalink to &quot;Objetivo y requisitos {#goal-and-prerequisites}&quot;">​</a></h2><p>Identifica el componente que falla y reúne un informe útil sin repetir efectos continuamente. Necesitas la versión, la hora aproximada y la operación intentada. Conserva una <a href="./backups.html">copia</a> antes de reiniciar o sustituir datos.</p><h2 id="inspect-the-nearest-evidence" tabindex="-1">Inspeccionar la evidencia cercana <a class="header-anchor" href="#inspect-the-nearest-evidence" aria-label="Permalink to &quot;Inspeccionar la evidencia cercana {#inspect-the-nearest-evidence}&quot;">​</a></h2><ol><li>Lee el error mostrado donde ocurrió el fallo. Usa su acción de diagnóstico o abre <strong>Diagnostics</strong> para inspeccionar las entradas relacionadas.</li><li>Filtra por origen, nivel o texto. Entre los orígenes útiles están LIVE, supervisión, plugins, cuenta, sincronización, actualizaciones, transporte, catálogo, instalación y colaboración.</li><li>Selecciona la entrada pertinente y conserva hora, código, identificadores de solicitud/entidad y descripción breve. Despliega los detalles disponibles.</li><li>Copia los diagnósticos filtrados o exporta el informe de texto. Si falla el portapapeles o la exportación, utiliza el texto alternativo mostrado. Revísalo antes de compartir y elimina tokens, cookies, enlaces de invitación y contenido privado.</li><li>Incluye una reproducción breve: página, creador/perfil/plugin seleccionado, acción, resultado esperado y resultado real. Indica si ocurrió antes o después de actualizar.</li></ol><h2 id="isolate-common-failures" tabindex="-1">Aislar fallos comunes <a class="header-anchor" href="#isolate-common-failures" aria-label="Permalink to &quot;Aislar fallos comunes {#isolate-common-failures}&quot;">​</a></h2><p>Si el feed está vacío, borra búsqueda y filtros, reanuda el desplazamiento y confirma la <a href="./../live/connections.html">conexión</a>. Pausar la vista no desconecta. Un aviso de pérdida visual no demuestra que puntos o estadísticas perdieran el mismo evento.</p><p>Si no se ejecuta una automatización, comprueba perfil activo, interruptores de evento/acción, disparador, rutas de campos y espera. Inspecciona el historial antes de modificar efectos. <strong>Test</strong> puede ejecutar audio, HTTP, puntos y acciones de plugins.</p><p>Para plugins, lee el error del trabajo de instalación o de conexión. Para Cloud, revisa la sesión y el área afectada en lugar de cambiar una cookie de TikTok. Para superposiciones, inspecciona pasarela y fuente. Para actualizaciones, consulta la <a href="./../updates.html">vía manual</a> cuando no se pueda instalar.</p><h2 id="expected-result-and-status" tabindex="-1">Resultado esperado y estado <a class="header-anchor" href="#expected-result-and-status" aria-label="Permalink to &quot;Resultado esperado y estado {#expected-result-and-status}&quot;">​</a></h2><p>Están disponibles filtros, copia y exportación de diagnósticos. Un paquete también requiere sus recursos web y el entorno de plataforma. En Linux, verifica GTK/WebKitGTK y una sesión X11/XWayland compatible; en Windows, WebView2. Consulta el alcance de <a href="./../requirements.html">requisitos</a>.</p><h2 id="recovery" tabindex="-1">Recuperación <a class="header-anchor" href="#recovery" aria-label="Permalink to &quot;Recuperación {#recovery}&quot;">​</a></h2><p>Repite después de corregir la causa concreta. Ante conflictos de revisión, carga y revisa el estado guardado actual. Si una orden remota queda sin confirmar, inspecciona su historial/estado antes de enviarla otra vez: el efecto puede haberse producido pese al tiempo de espera. Si falla el inicio, informa de paquete, versión y registro; evita borrar el directorio de datos.</p>',13)),t(o,{scenario:"diagnostics",locale:"es",tour:"diagnostics",title:"Demo de diagnostics"}),e[1]||(e[1]=a('<h2 id="operational-details" tabindex="-1">Detalles de operación <a class="header-anchor" href="#operational-details" aria-label="Permalink to &quot;Detalles de operación {#operational-details}&quot;">​</a></h2><p>Diagnostics es un registro UI en memoria, limitado a 2.000 entradas o 2 MiB. Agrupa repeticiones dentro de cinco segundos. Muestra inicialmente 100; exportar incluye todas las entradas filtradas, mientras <strong>Limpiar</strong> borra el registro entero. Copia/exporta antes de cerrar, reiniciar, limpiar o cambiar/cerrar una cuenta Cloud conocida: esos cambios vacían este historial.</p><p>Si no aparece ventana, revisa <code>tiktools.log</code> nativo (<code>controller.log</code> en modo controlador) en <code>%LOCALAPPDATA%/TikTools/logs</code> en Windows o <code>${XDG_DATA_HOME:-~/.local/share}/TikTools/logs</code> en Linux. <code>TIKTOOLS_HOME</code> cambia la raíz y <code>TIKTOOLS_LOG_DIR</code> sustituye el directorio de logs. Si falla el propio registro, puede no existir archivo; conserva el error de terminal/inicio disponible. Los logs nativos no garantizan la redacción de la UI: revisa todo antes de compartir.</p>',3))])}const b=i(l,[["render",c]]);export{g as __pageData,b as default};
